 async personaAllowed(c:pg.PoolClient,ctx:DbContext,lease:Lease,signal?:AbortSignal){const row=(await c.query('SELECT persona_snapshot_id,persona_context_state FROM runs WHERE id=$1',[lease.runId])).rows[0];if(!row)return false;if(lease.personaSnapshot)return !!this.personae&&row.persona_snapshot_id===lease.personaSnapshot.id&&!!await this.personae.current(c,ctx,lease,(...a)=>this.groupAudienceAllowed(...a),signal);return !row.persona_snapshot_id&&(['LEGACY_NONE','BUILTIN_ONLY'].includes(row.persona_context_state as string));}
