 async personaContextAllowed(c:pg.PoolClient,ctx:DbContext,lease:Lease,history:ProviderMessage[],signal?:AbortSignal){try{const expected=await this.personaMessage(c,ctx,lease,signal),messages=history.filter(m=>m.role==='system'&&m.content?.includes('FROZEN_PERSONA_STYLE_DATA'));return expected?messages.length===1&&history[0]===messages[0]&&messages[0]!.content?.endsWith('\n'+expected.content)===true:messages.length===0;}catch{return false;}}
