   const p=(await c.query("SELECT * FROM source_choice_replies WHERE id=$1 AND state='PENDING' AND worker_generation=$2 FOR UPDATE",[id,generation])).rows[0];if(!p)return null;
   const r=(await c.query('SELECT * FROM runs WHERE id=$1 FOR UPDATE',[p.run_id])).rows[0];if(!r)return null;
