   const budget=runtimeBudgetSchema.safeParse(r.budget);if(!budget.success||r.active_time_state!=='KNOWN'||Number(r.active_ms)>=budget.data.maxActiveMs||Number(r.model_turns)>=budget.data.maxTurns){await rejectChoiceReply(c,ctx,this.vault,id,'VERIFICATION_BUDGET_EXHAUSTED');await c.query("UPDATE runs SET status='PARTIAL',last_error=$2 WHERE id=$1 AND status='WAITING_USER'",[p.run_id,!budget.success?'INVALID_RUNTIME_BUDGET':r.active_time_state!=='KNOWN'?'LEGACY_ACTIVE_TIME_UNVERIFIED':Number(r.model_turns)>=budget.data.maxTurns?'MODEL_BUDGET_EXHAUSTED':'ACTIVE_TIME_BUDGET_EXHAUSTED']);return null;}
   const q=await loadChoice(c,ctx,this.vault,p.choice_id as string);
