   const review=(await c.query("SELECT id FROM run_narrative_reviews WHERE id=$1 AND run_id=$2 AND verdict='CLARIFICATION' AND answered_at IS NULL AND expires_at>clock_timestamp() FOR UPDATE",[reviewId,run.id])).rows[0];if(!review)return null;
