 async currentCheckpoint(c:pg.PoolClient,ctx:DbContext,lease:Lease):Promise<Checkpoint|null>{const q=await c.query('SELECT p.* FROM context_checkpoints p JOIN runs r ON r.tenant_id=p.tenant_id AND r.id=p.run_id AND r.provider_session_no=p.session_no WHERE p.run_id=$1',[lease.runId]);if(!q.rowCount)return null;const row=q.rows[0];if(new Date(row.expires_at as string).getTime()<=Date.now())throw new ContextRebuildRequired('JOURNAL_EXPIRED');try{return checkpointSchema.parse(JSON.parse(this.vault.open(row.checkpoint_ref as Sealed,`${ctx.tenantId}:${ctx.actorId}:checkpoint:${lease.runId}:${row.session_no}:${row.id}`)));}catch{throw new ContextIntegrity('CHECKPOINT_UNREADABLE');}}
